INSERT INTO monster VALUES (348,'Elemental','Fire Elemental, Small',NULL,'Small','Elemental','Fire, Extraplanar','2d8 (9 hp)','+5','50 ft. (10 squares)','15 (+1 size, +1 Dex, +3 natural), touch 12, flat-footed 14','+1','-3','Slam +3 melee (1d4 plus 1d4 fire)','Slam +3 melee (1d4 plus 1d4 fire)','5 ft.','5 ft.','Burn','Darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold','Fort +0, Ref +4, Will +0','Str 10, Dex 13, Con 10, Int 4, Wis 11, Cha 11','Listen +2, Spot +3','Improved Initiative, Weapon Finesse','Dodge',NULL,'Elemental Plane of Fire','Solitary','1','None','Usually neutral','3 HD (Small)','-','Burn (Ex)','Small fire elemental; CR 1; Small elemental (fire, extraplanar); HD 2d8; hp 9; Init +5; Spd 50 ft. (10 squares); AC 15 (+1 size, +1 dex, +3 natural), touch 12, flat-footed 14; Base Atk +1; Grp -3; Atk +3 melee (1d4 plus 1d4 fire, slam); Full Atk +3 melee (1d4 plus 1d4 fire, slam); Space/Reach 5 ft./5 ft.; SA Burn; SQ Darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold; AL N; SV Fort +0, Ref +4, Will +0; Str 10, Dex 13, Con 10, Int 4, Wis 11, Cha 11\n\nSkills and Feats: Listen +2, Spot +3; Dodge, Improved Initiative, Weapon Finesse','\n      <div topic=\"Fire Elemental\" level=\"3\"><p><h3>Fire Elemental</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Fire Elemental, Small</b><br/></td> \n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Elemental (Fire, Extraplanar)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8 (9 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+5<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+1 size, +1 Dex, +3 natural), touch 12, flat-footed 14<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +3 melee (1d4 plus 1d4 fire)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +3 melee (1d4 plus 1d4 fire)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Burn<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +4, Will +0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 13, Con 10, Int 4, Wis 11, Cha 11<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +2, Spot +3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Dodge, Improved Initiative <sup>B</sup>, Weapon Finesse <sup>B</sup><br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Elemental Plane of Fire<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>3 HD (Small)<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/><p>A fire elemental cannot enter water or any other nonflammable liquid. A body of water is an impassible barrier unless the fire elemental can step or jump over it.</p><p>Fire elementals speak Ignan, though they rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A fire elemental is a fierce opponent that attacks its enemies directly and savagely. It takes joy in burning the creatures and objects of the Material Plane to ashes.</p><div topic=\"Burn\" level=\"8\"><p><b>Burn (Ex):</b> A fire elemental\'s slam attack deals bludgeoning damage plus fire damage from the elemental\'s flaming body. Those hit by a fire elemental\'s slam attack also must succeed on a Reflex save or catch on fire. The flame burns for 1d4 rounds. The save DC varies with the elemental\'s size (see the table below). A burning creature can take a move action to put out the flame. The save DC is Constitution- based.</p><p>Creatures hitting a fire elemental with natural weapons or unarmed attacks take fire damage as though hit by the elemental\'s attack, and also catch on fire unless they succeed on a Reflex save.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\"><b>Fire Elemental Sizes</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Burn Save DC</b><br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>1 lb.<br/></td>\n<td>11<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>2 lb.<br/></td>\n<td>14<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>4 lb.<br/></td>\n<td>17<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>22<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>24<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>12 lb.<br/></td>\n<td>26<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
