INSERT INTO monster VALUES (350,'Elemental','Fire Elemental, Large',NULL,'Large','Elemental','Fire, Extraplanar','8d8+24 (60 hp)','+9','50 ft. (10 squares)','18 (-1 size, +5 Dex, +4 natural), touch 14, flat-footed 13','+6','+12','Slam +10 melee (2d6+2 plus 2d6 fire)','2 slams +10 melee (2d6+2 plus 2d6 fire)','10 ft.','10 ft.','Burn','Damage reduction 5/-, darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold','Fort +5, Ref +11, Will +2','Str 14, Dex 21, Con 16, Int 6, Wis 11, Cha 11','Listen +5, Spot +6','Improved Initiative, Weapon Finesse','Dodge, Mobility, Spring Attack',NULL,'Elemental Plane of Fire','Solitary','5','None','Usually neutral','9-15 HD (Large)','-','Burn (Ex)','Large fire elemental; CR 5; Large elemental (fire, extraplanar); HD 8d8+24; hp 60; Init +9; Spd 50 ft. (10 squares); AC 18 (-1 size, +5 dex, +4 natural), touch 14, flat-footed 13; Base Atk +6; Grp +12; Atk +10 melee (2d6+2 plus 2d6 fire, slam); Full Atk +10 melee (2d6+2 plus 2d6 fire, 2 slams); Space/Reach 10 ft./10 ft.; SA Burn; SQ Damage reduction 5/-, darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold; AL N; SV Fort +5, Ref +11, Will +2; Str 14, Dex 21, Con 16, Int 6, Wis 11, Cha 11\n\nSkills and Feats: Listen +5, Spot +6; Dodge, Improved Initiative, Mobility, Spring Attack, Weapon Finesse','\n      <div topic=\"Fire Elemental\" level=\"3\"><p><h3>Fire Elemental</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n \n<td><b>Fire Elemental, Large</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Large Elemental (Fire, Extraplanar)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>8d8+24 (60 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>18 (-1 size, +5 Dex, +4 natural), touch 14, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+6/+12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Slam +10 melee (2d6+2 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>2 slams +10 melee (2d6+2 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>Burn<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Damage reduction 5/-, darkvision 60 ft., elemental traits, immunity to fire, vulnerability to cold<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n\n<td>Fort +5, Ref +11, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n\n<td>Str 14, Dex 21, Con 16, Int 6, Wis 11, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n\n<td>Listen +5, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n\n<td>Dodge, Improved Initiative <sup>B</sup>, Mobility, Spring Attack, Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n\n<td>Elemental Plane of Fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n\n<td>9-15 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n</table><p/><p/><p>A fire elemental cannot enter water or any other nonflammable liquid. A body of water is an impassible barrier unless the fire elemental can step or jump over it.</p><p>Fire elementals speak Ignan, though they rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A fire elemental is a fierce opponent that attacks its enemies directly and savagely. It takes joy in burning the creatures and objects of the Material Plane to ashes.</p><div topic=\"Burn\" level=\"8\"><p><b>Burn (Ex):</b> A fire elemental\'s slam attack deals bludgeoning damage plus fire damage from the elemental\'s flaming body. Those hit by a fire elemental\'s slam attack also must succeed on a Reflex save or catch on fire. The flame burns for 1d4 rounds. The save DC varies with the elemental\'s size (see the table below). A burning creature can take a move action to put out the flame. The save DC is Constitution- based.</p><p>Creatures hitting a fire elemental with natural weapons or unarmed attacks take fire damage as though hit by the elemental\'s attack, and also catch on fire unless they succeed on a Reflex save.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\"><b>Fire Elemental Sizes</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Burn Save DC</b><br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>1 lb.<br/></td>\n<td>11<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>2 lb.<br/></td>\n<td>14<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>4 lb.<br/></td>\n<td>17<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>22<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>24<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>12 lb.<br/></td>\n<td>26<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
